package com.bookstore.service.impl; import com.bookstore.entity.Category; import com.bookstore.exception.ResourceNotFoundException; import com.bookstore.repository.CategoryRepository; import com.bookstore.service.CategoryService; import org.springframework.stereotype.Service; import java.util.*; @Service public class CategoryServiceImpl implements CategoryService{ private final CategoryRepository repo; public CategoryServiceImpl(CategoryRepository repo){this.repo=repo;} public List<Category> findAll(){return repo.findAll();} public Category findById(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Category not found: "+id));} public Category save(Category v){return repo.save(v);} public void delete(Long id){repo.delete(findById(id));} }